def flatten_list(list1):
    result_list = []
    if not list1: return result_list
    stack = [list(list1)]
    while stack:
        c_num = stack.pop()
        next = c_num.pop()
        if c_num: stack.append(c_num)
        if isinstance(next, list):
            if next and not (len(next) == 1 and isinstance(next[0], list)):
                stack.append(list(next))
        else: result_list.append(next)
    result_list.reverse()
    return result_list

