from itertools import groupby 
def extract_elements(numbers, n):
    result = []
    groups = [(i, len(list(j))) for i, j in groupby(numbers)]
    for idx, (value, count) in enumerate(groups):
        if idx == len(groups) - 1:
            if count >= n:
                result.append(value)
        elif count == n:
            result.append(value)
    return result

