def is_abundant(n):
    fctrsum = 0
    for fctr in range(1, int(n ** 0.5) + 1):
        if n % fctr == 0:
            fctrsum += fctr
            if fctr != 1:
                fctrsum += n // fctr
    return fctrsum > n

